import React, { useEffect, useState } from "react";

export default function BuyLandList() {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [predictions, setPredictions] = useState({}); // { [id]: { price, price_per_sqft, price_per_cent } }
  const [error, setError] = useState("");

  useEffect(() => {
    let mounted = true;
    async function load() {
      try {
        const res = await fetch(`${process.env.REACT_APP_BACKEND_URL}/buy/lands`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        if (mounted) setItems(Array.isArray(data) ? data : []);
      } catch (e) {
        if (mounted) setError(e?.message || "Failed to load lands");
      } finally {
        if (mounted) setLoading(false);
      }
    }
    load();
    return () => { mounted = false; };
  }, []);

  async function handlePredict(land) {
    try {
      const payload = {
        Area_sqft: Number(land.area_sqft) || 0,
        zoning: land.zoning || "Residential",
        latitude: Number(land.latitude) || 0,
        longitude: Number(land.longitude) || 0,

        waterApplicable: land.waterApplicable || "applicable",
        waterDistance: Number(land.waterDistance) || 0,
        roadApplicable: land.roadApplicable || "applicable",
        roadDistance: Number(land.roadDistance) || 0,
        schoolApplicable: land.schoolApplicable || "applicable",
        schoolDistance: Number(land.schoolDistance) || 0,
        railwayApplicable: land.railwayApplicable || "applicable",
        railwayDistance: Number(land.railwayDistance) || 0,
        busApplicable: land.busApplicable || "applicable",
        busDistance: Number(land.busDistance) || 0
      };

      const res = await fetch(`${process.env.REACT_APP_LAND_API}/predict/land`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });

      if (!res.ok) {
        const text = await res.text();
        throw new Error(text || `HTTP ${res.status}`);
      }

      const data = await res.json();
      setPredictions(prev => ({ ...prev, [land.id]: data }));
    } catch (e) {
      alert(`Prediction failed: ${e?.message || e}`);
    }
  }

  if (loading) return <div className="page">Loading lands...</div>;
  if (error) return <div className="page error">Error: {error}</div>;

  return (
    <div className="page buy-land">
      <h2>Buy Land</h2>
      <div className="grid">
        {items.map(item => (
          <div key={item.id} className="card">
            <div className="thumb-wrap">
              <img
                className="thumb"
                src={item.image ? `${process.env.REACT_APP_BACKEND_URL}${item.image}` : "/placeholder.png"}
                alt="land"
              />
              <span className="badge">Land</span>
            </div>

            <div className="meta">
              <div className="title">{item.location || item.city || "Land"}</div>
              <div className="line">Area: {item.area_sqft ? `${item.area_sqft} sqft` : "NA"}</div>
              <div className="line">Zoning: {item.zoning || "NA"}</div>
              <div className="line">Lat/Lng: {item.latitude ?? "NA"}, {item.longitude ?? "NA"}</div>
              {item.actualPrice != null && (
                <div className="line">Listed Price: ₹{Number(item.actualPrice).toLocaleString("en-IN")}</div>
              )}
            </div>

            <div className="actions">
              <button className="btn btn-success" onClick={() => handlePredict(item)}>
                Predict
              </button>
              <a className="btn btn-primary" href={`tel:${item.contact || ""}`}>Contact</a>
            </div>

            {predictions[item.id] && (
              <div className="pred-box">
                <div>Estimated total: ₹{predictions[item.id].price?.toLocaleString("en-IN")}</div>
                <div>₹/sqft: ₹{predictions[item.id].price_per_sqft != null ? predictions[item.id].price_per_sqft.toLocaleString("en-IN") : "N/A"}</div>
                <div>₹/cent: ₹{predictions[item.id].price_per_cent != null ? predictions[item.id].price_per_cent.toLocaleString("en-IN") : "N/A"}</div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}
